#include <iostream>
#include <limits>

// tryReadInt() extracts one int from std::cin, then recovers the stream.
// Contract: return the extracted value when extraction succeeded, -1 otherwise.
int tryReadInt()
{
    int value {};
    std::cin >> value;

    bool ok = static_cast<bool>(std::cin);  // 1. snapshot BEFORE clear
    std::cin.clear();                       // 2. reset any failure state
    std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n'); // 3. drain line
    return ok ? value : -1;                 // 4. decide
}

